#!/usr/bin/env python3
"""Create a reproducible coverage report; do not interpret absent values as zero."""
import datetime,sqlite3
from pathlib import Path
p=Path(__file__).resolve().parent;c=sqlite3.connect(p/'artificial_analysis.sqlite3',timeout=60)
def row(q):return c.execute(q).fetchone()
queue=dict(c.execute('select status,count(*) from crawl_queue group by status'))
pending_tables=row('select count(*) from page_archive p left join table_extraction_log l on l.url=p.url where l.page_sha256 is null or l.page_sha256<>p.sha256')[0]
models,scores,benchmarks=row('select count(distinct model_id),count(*),count(distinct evaluation_slug) from latest_combined_benchmark_scores')
totalcosts=row('select count(*) from model_index_total_costs')[0]
details=row('select count(*),count(distinct model_id) from model_details')
missing_model_details=row('select count(*) from embedded_latest_models e where not exists (select 1 from model_details d where d.model_id=e.model_id)')[0]
index=row('select count(*),count(distinct model_id),count(score),count(cost_per_task_usd_inferred),count(time_per_task_seconds_inferred) from latest_index_benchmark_results')
providers=row('select count(*),count(distinct model_slug),count(cost_per_task_usd),count(time_per_task_minutes) from all_provider_observations')
providerpages=row('select count(*),count(distinct provider_slug),count(distinct model_name),count(cost_per_task_usd),count(time_per_task_minutes) from provider_page_models')
agents=row('select count(distinct run_id),count(distinct agent_slug),count(distinct model_name) from coding_agent_latest_runs')
search=row('select count(*),count(search_cost_usd_per_1000),count(time_per_task_seconds) from latest_search_api_observations')
price_context=row('select (select count(*) from provider_identities),(select count(*) from provider_price_scenarios),(select count(*) from provider_tiered_pricing),(select count(*) from cache_pricing_source_rows),(select count(*) from chatbot_plan_observations)')
endpoints=row('select count(*),count(distinct endpoint_id),count(distinct host_slug) from provider_endpoint_records')
media=row("select (select count(*) from media_arena_observations),(select count(distinct endpoint_id) from media_endpoint_records where modality='image'),(select count(distinct endpoint_id) from media_endpoint_records where modality='video'),(select count(distinct endpoint_id) from media_endpoint_records where modality='text-to-speech')")
speech=row('select (select count(*) from speech_to_speech_observations),(select count(*) from speech_to_text_observations),(select count(*) from streaming_speech_observations),(select count(*) from tts_arena_observations)')
harvey=row('select count(*),count(cost_per_task_usd) from harvey_exact_task_costs')
speech_agent=row("select count(distinct host_model_id),count(distinct case when average_cost_usd_per_task is not null then host_model_id end),count(distinct case when time_to_first_audio_seconds is not null then host_model_id end) from speech_agent_benchmark_observations where benchmark='Big Bench Audio'")
decision=row('select count(*),count(distinct contestant_slug),count(distinct dataset_slug) from decision_dataset_benchmark_results')
bcost=row('select count(*),count(distinct model_id),count(distinct benchmark_slug) from benchmark_cost_estimates')
btime=row('select count(*),count(estimated_seconds_per_task),count(distinct benchmark_slug) from benchmark_generation_time_estimates')
vials=row('select count(*) from vials_estimated_time_per_task')[0]
searchdetails=row('select count(*) from search_agent_details')
breakdowns=row('select count(*) from benchmark_named_breakdown_facts')
log_names=('table_extraction_log','model_extraction_log','evaluation_extraction_log','coding_agent_extraction_log','provider_endpoint_extraction_log','media_endpoint_extraction_log')
tables={x[0] for x in c.execute("select name from sqlite_master where type='table'")}
log_errors={name:c.execute('select count(*) from '+name+' where error is not null').fetchone()[0] for name in log_names if name in tables}
failed_steps=[]
if 'pipeline_step_runs' in tables:
 failed_steps=list(c.execute("select p.script,p.status from pipeline_step_runs p where p.id=(select max(q.id) from pipeline_step_runs q where q.script=p.script) and p.status!='ok'"))
arena_expected=('https://artificialanalysis.ai/image/leaderboard/editing','https://artificialanalysis.ai/image/leaderboard/text-to-image','https://artificialanalysis.ai/video/leaderboard/image-to-video','https://artificialanalysis.ai/video/leaderboard/text-to-video','https://artificialanalysis.ai/video/leaderboard/video-editing')
arena_missing=[u for u in arena_expected if c.execute('select count(*) from media_arena_observations where source_url=?',(u,)).fetchone()[0]==0]
archive_check=c.execute("select count(*),coalesce(sum(case when a.status='ok' then 1 else 0 end),0),coalesce(sum(case when a.status in ('error','mismatch') then 1 else 0 end),0) from page_archive p left join archive_integrity_checks a on a.source_url=p.url and a.page_sha256=p.sha256").fetchone() if 'archive_integrity_checks' in tables else None
missing=list(c.execute("select coalesce(cast(http_status as text),'kein Status'),count(*) from crawl_queue where status='error' group by http_status"))
text=f'''# Erfassungsstand\n\nErstellt: {datetime.datetime.now(datetime.timezone.utc).isoformat()}\n\n- Seiten: {queue.get('ok',0)} erfolgreich, {queue.get('pending',0)} ausstehend, {queue.get('error',0)} fehlgeschlagen. Warteschlange umfasst Sitemap und entdeckte Links; sie belegt keine Vollständigkeit der Website.\n- Tabellenextraktion: {pending_tables} archivierte Seiten warten auf Verarbeitung oder erneute Verarbeitung nach Hashänderung.\n- Kombinierte Modell- und Evaluierungsseiten: {models} Modell-IDs mit {scores} Score-Einträgen über {benchmarks} Benchmark- und Indexbezeichnungen; die Quell-Registry umfasst {row('select count(*) from benchmark_registry')[0]} Zuordnungen.\n- Modelldetailseiten: {details[0]} Quelldatensätze für {details[1]} eindeutige IDs; {missing_model_details} IDs aus dem zuletzt erfassten Modelllistenstand ohne entsprechendes Detailobjekt.\n- Index-Gesamtkosten: {totalcosts} Modellvarianten; nicht mit Kosten je Aufgabe verwechseln.\n- Index-Benchmarkzeilen: {index[0]} für {index[1]} Modell-IDs, davon {index[2]} mit Score, {index[3]} mit Kosten und {index[4]} mit Zeit.\n- Modell-Providerseiten: {providers[0]} Quellzeilen für {providers[1]} Modell-Slugs, davon {providers[2]} mit Kosten und {providers[3]} mit Zeit.\n- Providerseiten: {providerpages[0]} Quellzeilen für {providerpages[1]} Provider-Slugs und {providerpages[2]} Modellnamen, davon {providerpages[3]} mit Kosten und {providerpages[4]} mit Zeit.\n- Provider-Endpunkte: {endpoints[0]} quellbezogene Zeilen, {endpoints[1]} eindeutige Endpunkt-IDs, {endpoints[2]} Provider-Slugs; Abweichungen zwischen Quellarrays bleiben getrennt.\n- Provider-Preisdetails: {price_context[0]} belegte Provider-Identitäten, {price_context[1]} Mischpreisszenarien, {price_context[2]} Staffelzeilen, {price_context[3]} Cache-Tabellenzeilen und {price_context[4]} Chatbot-Abos; diese Einheiten und Preisarten nicht vermischen.\n- Bild-/Video-Arena: {media[0]} quellbezogene Score-Zeilen; {media[1]} Bild-, {media[2]} Video- und {media[3]} TTS-Endpunkt-IDs.\n- Sprachdaten: {speech[0]} Speech-to-Speech-, {speech[1]} Speech-to-Text-, {speech[2]} Streaming- und {speech[3]} Text-to-Speech-Arena-Zeilen.\n- Coding-Agenten: {agents[0]} eindeutige Run-IDs, {agents[1]} Agenten-Slugs und {agents[2]} Modellnamen.\n- Such-API: {search[0]} zuletzt erfasste Varianten, {search[1]} mit Suchkosten je 1.000 Aufgaben und {search[2]} mit Zeit; {searchdetails[0]} detaillierte Such-Agenten-Konfigurationen.\n- Harvey-LAB: {harvey[0]} Modellzeilen, {harvey[1]} mit von der Quelle berechneten Durchschnittskosten.\n- Big-Bench-Audio: {speech_agent[0]} Konfigurationen, {speech_agent[1]} mit durchschnittlichen Aufgabenpreisen und {speech_agent[2]} mit Zeit bis zum ersten Audio.\n- Decision-Benchmarks: {decision[0]} Datensatz-Konfigurationspaare mit Score, Kosten und Medianzeit für {decision[1]} Konfigurationen und {decision[2]} Datensätze.\n- Benchmark-Kostenschätzungen: {bcost[0]} Werte für {bcost[1]} Modell-IDs über {bcost[2]} Benchmarks; nach Quellformel und hinterlegten Preisen berechnet.\n- Benchmark-Zeitschätzungen: {btime[0]} Zeilen über {btime[2]} Benchmarks, {btime[1]} berechenbar; keine Einzelmessungen.\n- VIALS: {vials} modellbezogene Zeitschätzungen; keine gemessenen Einzelzeiten.\n- Benchmark-Unterwerte: {breakdowns[0]} quellbezogene benannte Detailfelder; nicht alle Werte sind eigenständige Scores.\n- Fehler nach HTTP-Status: {missing}.\n- Letzter bekannter Fehlerstatus je Pipeline-Schritt: {failed_steps}; Fehler in Extraktionslogs: {log_errors}.\n- Arena-Basisranglisten ohne extrahierte Werte: {arena_missing}.\n- Archiv-Hashprüfung (aktuelle Seiten / bei gleichem gespeicherten Hash zuletzt OK / fehlerhaft): {archive_check}; ungeprüfte neue Seiten ergeben sich aus der Differenz. Eine erneute Vollprüfung ist mit verify_archive.py --full möglich.\n- SQLite quick_check: {row('pragma quick_check')[0]}.\n\nZahlen und Quellenstände können sich laufend ändern. Fehlende Werte sind nicht 0; gleiche Namen sind nicht zwingend stabile Identitäten. Index-Aufgabenkosten und -zeiten basieren auf abgeleiteten Einheiten; Details und Grenzen siehe README.md.\n'''
(p/'COVERAGE.md').write_text(text,encoding='utf8');print(text)
